void refresh_replay_list(const Snapshot& s){
    static std::vector<std::wstring> previous_rows;
    static std::vector<fs::path> previous_paths;
    std::vector<std::wstring> rows;
    for(const auto&e:s.replays){std::wostringstream row;const auto sys_time=std::chrono::system_clock::now()+(e.modified-fs::file_time_type::clock::now());const auto tm=std::chrono::system_clock::to_time_t(sys_time);std::tm date{};localtime_s(&date,&tm);const auto version=std::wstring(e.summary.metadata.game_version.begin(),e.summary.metadata.game_version.end());row<<e.path.filename().wstring()<<L" | "<<time_text(e.summary.duration_ns)<<L" | "<<e.summary.sample_count<<L" samples | "<<std::fixed<<std::setprecision(2)<<double(e.bytes)/(1024.0*1024.0)<<L" MiB | "<<version<<L" | "<<std::put_time(&date,L"%Y-%m-%d %H:%M");rows.push_back(row.str());}
    if(rows==previous_rows)return;
    const auto selected=static_cast<int>(SendMessageW(app.list,LB_GETCURSEL,0,0));
    const auto top=SendMessageW(app.list,LB_GETTOPINDEX,0,0);
    fs::path selected_path;
    if(selected>=0&&static_cast<std::size_t>(selected)<previous_paths.size())selected_path=previous_paths[selected];
    SendMessageW(app.list,WM_SETREDRAW,FALSE,0);
    SendMessageW(app.list,LB_RESETCONTENT,0,0);
    previous_paths.clear();
    for(std::size_t i=0;i<rows.size();++i){
        SendMessageW(app.list,LB_ADDSTRING,0,reinterpret_cast<LPARAM>(rows[i].c_str()));
        previous_paths.push_back(s.replays[i].path);
        if(s.replays[i].path==selected_path)SendMessageW(app.list,LB_SETCURSEL,i,0);
    }
    if(!rows.empty())SendMessageW(app.list,LB_SETTOPINDEX,std::clamp<LRESULT>(top,0,static_cast<LRESULT>(rows.size()-1)),0);
    previous_rows=std::move(rows);
    SendMessageW(app.list,WM_SETREDRAW,TRUE,0);
    InvalidateRect(app.list,nullptr,FALSE);
}
void update_ui(){Snapshot s;{std::lock_guard lock(app.mutex);s=app.data;}set_text(app.connection,s.connected?L"Connection: CONNECTED  |  Game: Elden Ring 1.17":L"Connection: WAITING FOR GAME MODULE");set_text(app.player,s.player?L"Player: FOUND":L"Player: WAITING");const wchar_t* states[]={L"READY",L"RECORDING",L"PAUSED",L"SAVING...",L"READY",L"ERROR"};SetWindowTextW(app.recording,(std::wstring(L"Recorder: ")+states[static_cast<int>(s.state)]+L"     Duration: "+time_text(s.active_ns)).c_str());std::wostringstream st;st<<L"Samples: "<<s.samples<<L"    Incoming: "<<std::fixed<<std::setprecision(1)<<s.rate<<L" Hz    IPC latency: "<<std::setprecision(2)<<s.latency_ms<<L" ms\r\nData: "<<std::setprecision(3)<<double(s.bytes)/(1024.0*1024.0)<<L" MiB    Dropped samples: "<<s.dropped<<L"    Reconnects: "<<s.reconnects;if(!s.error.empty())st<<L"\r\n"<<s.error;SetWindowTextW(app.stats,st.str().c_str());EnableWindow(app.button_start,s.connected&&s.player&&s.state!=erplay::RecordingState::recording&&s.state!=erplay::RecordingState::paused&&s.state!=erplay::RecordingState::saving);EnableWindow(app.button_pause,s.state==erplay::RecordingState::recording);EnableWindow(app.button_resume,s.state==erplay::RecordingState::paused);EnableWindow(app.button_stop,s.state==erplay::RecordingState::recording||s.state==erplay::RecordingState::paused);refresh_replay_list(s);EnableWindow(app.button_open,!s.replays.empty());EnableWindow(app.button_delete,!s.replays.empty());EnableWindow(app.button_rename,!s.replays.empty());update_replay_panel();}

